INSERT INTO "DriverContractVersion" (
  "id", "version", "content", "changeSummary", "graceDays",
  "requireForNewTrips", "createdBy", "publishedBy", "publishedAt", "updatedAt"
) VALUES (
  'official-driver-partnership-v2.3', 'v2.3',
  $contract${
  "code": "GOVIET247_DRIVER_PARTNERSHIP",
  "title": "HỢP ĐỒNG HỢP TÁC TÀI XẾ VÀ SỬ DỤNG NỀN TẢNG GOVIET247",
  "version": "v2.3",
  "sections": [
    {
      "heading": "THÔNG TIN CÁC BÊN",
      "paragraphs": [
        "Bên A: CÔNG TY TNHH CÔNG NGHỆ VINA LIGHTHOUSE",
        "Mã số thuế: 0317762423",
        "Địa chỉ: Số 33/4 Đường Đặng Văn Ngữ, Khu phố 6, Phường Phú Nhuận, TP Hồ Chí Minh, Việt Nam",
        "Người đại diện: NGUYỄN TRỌNG ĐĂNG",
        "Chức vụ: Giám đốc",
        "Bên B: CÁ NHÂN THAM GIA HỢP TÁC KINH DOANH",
        "Họ và tên: [........................................................]",
        "Số định danh cá nhân: [.............................................]",
        "Mã số thuế (nếu đã có): [...........................................]",
        "Địa chỉ: [....................................................................]",
        "Số điện thoại: [..........................................................]",
        "Tài khoản nhận tiền: [................................................]",
        "Người lái và phương tiện: [Đối chiếu hồ sơ/phụ lục]",
        "Ngày hiệu lực: [Điền khi giao kết]"
      ]
    },
    {
      "heading": "1. PHẠM VI VÀ MỤC ĐÍCH HỢP TÁC",
      "paragraphs": [
        "Bên A cung cấp quyền sử dụng nền tảng GoViet247, hỗ trợ kết nối nhu cầu chuyến đi với Bên B, ghi nhận giao dịch và đối soát các khoản phát sinh. Bên B đóng góp công sức, phương tiện được phép sử dụng và các điều kiện hành nghề cần thiết để thực hiện chuyến đã nhận theo quy định pháp luật.",
        "Việc hợp tác không thành lập pháp nhân mới và không chuyển quyền sở hữu phương tiện hoặc phần mềm. Không phát sinh tài sản chung hoặc nghĩa vụ góp vốn, trừ khi hai bên có thỏa thuận riêng bằng văn bản. Bên B chỉ thực hiện dịch vụ trong phạm vi giấy phép, điều kiện kinh doanh và tư cách tham gia vận tải phù hợp; thỏa thuận này không thay thế giấy phép hoặc hợp đồng vận tải bắt buộc.",
        "Bên B chủ động lựa chọn thời gian hoạt động và chuyến nhận; Bên A không cam kết mức thu nhập hoặc số chuyến tối thiểu. Việc xác định quan hệ lao động, tư cách kinh doanh và nghĩa vụ pháp lý căn cứ nội dung, cách thực hiện thực tế và pháp luật, không chỉ căn cứ tên gọi của hợp đồng.",
        "Thông tin giao dịch phải xác định được bên cung cấp dịch vụ vận tải cho hành khách và bên cung cấp dịch vụ nền tảng. Vai trò, trách nhiệm và điều kiện kinh doanh của mỗi bên được xác định theo hoạt động thực tế, bao gồm cách xác định giá, điều hành chuyến, giao kết và thanh toán, cùng các quy định bắt buộc áp dụng."
      ]
    },
    {
      "heading": "2. THÔNG TIN VÀ ĐIỀU KIỆN THAM GIA",
      "paragraphs": [
        "Bên B cung cấp đầy đủ, trung thực họ tên, số định danh cá nhân hoặc mã số thuế phù hợp, địa chỉ cư trú, điện thoại, tài khoản nhận tiền và hồ sơ phương tiện, giấy phép, bảo hiểm cần thiết. Bên B thông báo thay đổi kịp thời và chịu trách nhiệm về thông tin do mình cung cấp; Bên A có trách nhiệm kiểm tra trong phạm vi công việc của mình.",
        "Bên B không được giao tài khoản cho người khác hoặc thực hiện chuyến khi không đủ điều kiện. Trường hợp hoạt động thông qua đơn vị kinh doanh vận tải, thông tin và căn cứ tham gia của đơn vị đó phải được bổ sung vào hồ sơ trước khi thực hiện.",
        "Bên B có thể tạo tài khoản trước và bổ sung hồ sơ theo hướng dẫn. Quyền nhận chuyến chỉ được mở sau khi Bên A xác thực thông tin và giấy tờ cần thiết theo tư cách cung ứng, người lái, phương tiện và quy định áp dụng. Nếu người lái thực hiện chuyến cho một đơn vị vận tải, hồ sơ ghi rõ tên đơn vị, tư cách đại diện và mối liên hệ với người lái và phương tiện."
      ]
    },
    {
      "heading": "3. GIAO KẾT VÀ THỰC HIỆN CHUYẾN",
      "paragraphs": [
        "Trước khi nhận chuyến, Bên B được xem hành trình, thời gian, loại xe, mức cước trọn gói, số tiền cần thu khách và phí nền tảng áp dụng. Bên B có thể nhận hoặc từ chối chuyến trước khi xác nhận.",
        "Sau khi xác nhận, Bên B thu đúng số tiền hiển thị cho chuyến và không tự ý thu thêm hoặc đổi giá. Nếu khách yêu cầu đổi hành trình hoặc phát sinh dịch vụ, Bên B liên hệ bộ phận hỗ trợ để cập nhật và xác nhận lại với khách trước khi thu khoản điều chỉnh.",
        "Chỉ ghi nhận chuyến hoàn thành khi có căn cứ thực tế. Hủy chuyến, thay đổi giá, hoàn tiền và khiếu nại phải được ghi nhận cùng lý do và chứng từ. Hai bên phối hợp giải quyết sự cố theo trách nhiệm và lỗi thực tế của từng bên."
      ]
    },
    {
      "heading": "4. QUYỀN LỢI VÀ PHÍ SỬ DỤNG NỀN TẢNG",
      "paragraphs": [
        "Quyền lợi của Bên A là phí kết nối hoặc phí sử dụng nền tảng theo thỏa thuận áp dụng cho từng chuyến. Khoản thu của Bên B được xác định từ giá trị dịch vụ Bên B được hưởng, trừ các khoản phí, thuế hoặc điều chỉnh thuộc trách nhiệm Bên B theo pháp luật và thỏa thuận. Mọi khoản phải thể hiện tách bạch trên bảng đối soát.",
        "Mức phí hoặc tỷ lệ phí, căn cứ tính, việc đã bao gồm hay chưa bao gồm VAT và thời điểm áp dụng phải được ghi trong phụ lục hoặc hiển thị để Bên B chấp thuận trước khi nhận chuyến. Không mặc định một tỷ lệ hoa hồng hoặc thuế suất chung cho mọi thời kỳ. Thay đổi phí chỉ áp dụng cho giao dịch tương lai đã được thông báo và chấp thuận; không tự sửa khoản phí của chuyến đã hoàn thành.",
        "Phí nền tảng, tiền thu hộ hoặc chi hộ, khoản nạp ví và khoản thuế giữ lại để nộp thay là các khoản khác nhau. Việc phân loại doanh thu kế toán, thuế của mỗi bên thực hiện theo bản chất giao dịch và quy định áp dụng; không dùng số dư ví để thay cho doanh thu hoặc chứng từ nộp thuế."
      ]
    },
    {
      "heading": "5. THANH TOÁN VÀ ĐỐI SOÁT",
      "paragraphs": [
        "Đối với chuyến trả trực tiếp, hành khách thanh toán cước cho bên cung cấp dịch vụ vận tải theo thông tin chuyến.",
        "Đối với chuyến có thu hộ, trả trước hoặc thanh toán qua tài khoản đối tác, điều kiện chuyến phải thể hiện rõ bên nhận tiền, khoản đã thanh toán, số tiền còn phải thu và cách đối soát.",
        "Hai bên ghi nhận riêng cước vận tải, phí nền tảng, khoản thu hộ hoặc chi hộ và các khoản điều chỉnh theo giao dịch thực tế.",
        "Bên B đồng ý để Bên A khấu trừ hoặc bù trừ trên số dư tài khoản ví nội bộ các khoản phí nền tảng, các khoản thuế mà Bên A có trách nhiệm khai, nộp thay cho Bên B theo quy định pháp luật và trong phạm vi ủy quyền tại Hợp đồng này, và các khoản điều chỉnh có căn cứ.",
        "Mỗi khoản phải có nội dung, số tiền, thời điểm và mã giao dịch; không thu hai lần cùng một nghĩa vụ. Khoản giữ tạm chưa xác định không được ghi là đã nộp thuế.",
        "Hai bên được tra cứu giao dịch phát sinh trên ứng dụng, đối soát định kỳ theo tháng và xử lý sai lệch khi có yêu cầu. Kỳ đối soát tháng không tự thay đổi thời điểm lập hóa đơn, khấu trừ hoặc khai nộp thuế theo luật.",
        "Bên B gửi yêu cầu đối chiếu trong 07 ngày làm việc từ khi nhận bảng; việc không phản hồi không loại trừ quyền yêu cầu sửa sai hoặc nghĩa vụ bắt buộc theo pháp luật.",
        "Việc hoàn trả khoản giữ, xử lý chuyến hủy và rút số dư thực hiện theo nghĩa vụ thực tế, quy trình công bố và thời hạn đã thông báo. Bên A phải nêu rõ lý do, căn cứ và thời gian dự kiến nếu tạm giữ hoặc từ chối rút tiền."
      ]
    },
    {
      "heading": "6. HÓA ĐƠN VÀ NGHĨA VỤ THUẾ",
      "paragraphs": [
        "Mỗi bên thực hiện nghĩa vụ hóa đơn, thuế đối với doanh thu và hoạt động thuộc trách nhiệm của mình theo quy định pháp luật tại thời điểm phát sinh.",
        "Bên A lập hóa đơn đối với phí nền tảng thuộc trách nhiệm của Bên A. Chủ thể phải lập hóa đơn đối với dịch vụ vận tải được xác định theo tư cách cung cấp dịch vụ thực tế và quy định pháp luật."
      ]
    },
    {
      "heading": "6.1. ỦY QUYỀN ĐĂNG KÝ THUẾ, KHAI VÀ NỘP THUẾ THAY",
      "paragraphs": [
        "Đối với thu nhập kinh doanh của Bên B phát sinh từ hoạt động hợp tác kinh doanh thông qua nền tảng GoViet247, Bên B đồng ý ủy quyền cho Bên A thực hiện các thủ tục đăng ký thuế, khai thuế và nộp thuế thay cho Bên B trong phạm vi pháp luật cho phép và theo quy định pháp luật từng thời kỳ.",
        "Phạm vi ủy quyền chỉ áp dụng đối với doanh thu, thu nhập và nghĩa vụ thuế phát sinh từ hoạt động hợp tác kinh doanh thông qua nền tảng GoViet247 thuộc phạm vi Hợp đồng này, không bao gồm doanh thu, thu nhập hoặc nghĩa vụ thuế phát sinh từ hoạt động khác của Bên B.",
        "Bên A thực hiện đăng ký thuế cho Bên B trong trường hợp pháp luật quy định Bên A có trách nhiệm hoặc được thực hiện việc đăng ký thuế thay.",
        "Bên A thực hiện khai và nộp các khoản thuế của Bên B mà pháp luật quy định Bên A phải khai, nộp thay hoặc được Bên B ủy quyền thực hiện.",
        "Trường hợp pháp luật hoặc cơ quan thuế yêu cầu văn bản, biểu mẫu hoặc hồ sơ ủy quyền riêng để thực hiện đăng ký thuế, khai thuế hoặc nộp thuế thay, Bên B có trách nhiệm ký và cung cấp hồ sơ theo yêu cầu để Bên A thực hiện thủ tục."
      ]
    },
    {
      "heading": "6.2. XÁC ĐỊNH DOANH THU VÀ SỐ THUẾ",
      "paragraphs": [
        "Căn cứ tính thuế, doanh thu tính thuế, sắc thuế, mức thuế, thời điểm xác định nghĩa vụ thuế, kỳ khai thuế và các trường hợp miễn, giảm, hoàn hoặc không phát sinh nghĩa vụ thuế được xác định theo quy định pháp luật và hồ sơ, giao dịch thực tế của Bên B.",
        "Bên A thông báo cho Bên B về doanh thu làm căn cứ tính thuế, số thuế dự kiến khấu trừ/giữ lại và số thuế đã khai, nộp thay trong phạm vi pháp luật cho phép.",
        "Hợp đồng này không mặc định áp dụng một mức thuế cố định cho mọi tài xế hoặc mọi thời kỳ."
      ]
    },
    {
      "heading": "6.3. THEO DÕI VÀ CUNG CẤP CHỨNG TỪ",
      "paragraphs": [
        "Bên A theo dõi riêng các khoản thuế đã giữ, đã khai, đã nộp và các khoản điều chỉnh liên quan đến Bên B.",
        "Bên A cung cấp cho Bên B bảng chi tiết, thông tin hoặc chứng từ chứng minh việc khai, nộp thuế thay trong phạm vi pháp luật cho phép.",
        "Hai bên phối hợp xử lý các trường hợp kê khai bổ sung, điều chỉnh, hoàn/bù trừ thuế và sai lệch số liệu phát sinh.",
        "Việc Bên A giữ lại tiền thuế hoặc việc Bên B xác nhận trên ứng dụng không đồng nghĩa với việc nghĩa vụ thuế đã hoàn thành nếu Bên A chưa thực hiện việc khai, nộp theo quy định."
      ]
    },
    {
      "heading": "6.4. PHẠM VI TRÁCH NHIỆM",
      "paragraphs": [
        "Bên A không chịu trách nhiệm thay cho các nghĩa vụ thuế của Bên B phát sinh ngoài phạm vi hoạt động hợp tác kinh doanh thông qua nền tảng GoViet247, trừ trường hợp hai bên có thỏa thuận hoặc ủy quyền riêng phù hợp quy định pháp luật.",
        "Bên A không tự động được thay đổi thông tin đăng ký thuế hoặc thực hiện quyết toán thay cho các nghĩa vụ riêng khác của Bên B nếu pháp luật không quy định hoặc Bên B không có ủy quyền phù hợp."
      ]
    },
    {
      "heading": "7. QUYỀN VÀ TRÁCH NHIỆM CỦA MỖI BÊN",
      "paragraphs": [
        "Bên A duy trì công cụ tra cứu và hỗ trợ, công khai cách tính phí, ghi nhận đầy đủ giao dịch và cung cấp thông tin đối soát. Bên A chỉ tạm ngừng tài khoản hoặc giữ khoản tiền khi có căn cứ và phải thông báo lý do, phạm vi, đầu mối giải quyết; xử lý tình huống khẩn cấp theo yêu cầu an toàn hoặc pháp luật.",
        "Bên B thực hiện chuyến an toàn, giữ gìn phương tiện, tuân thủ pháp luật và cung cấp chứng từ cần thiết; được nhận khoản thuộc quyền lợi của mình, tra cứu số liệu và khiếu nại các khoản phí hoặc thuế. Không bên nào được yêu cầu bên kia lập hồ sơ khống, ghi sai ngày giao kết hoặc xác nhận thay sự đồng ý chưa phát sinh.",
        "Bên vi phạm bồi thường thiệt hại thực tế theo lỗi, quan hệ nhân quả và quy định pháp luật. Trách nhiệm với người thứ ba và cơ quan nhà nước được xác định theo pháp luật; thỏa thuận nội bộ không loại trừ trách nhiệm bắt buộc.",
        "Khi xử lý phản ánh, Bên A thông báo nội dung cần xác minh và cho Bên B cơ hội cung cấp thông tin. Nếu có khoản điều chỉnh, Bên A nêu lý do, số tiền và giao dịch liên quan để Bên B đối chiếu. Nếu có nguy cơ an toàn cần xử lý ngay, Bên A có thể tạm hạn chế nhận chuyến trong thời gian xác minh và thông báo cho Bên B."
      ]
    },
    {
      "heading": "8. BẢO VỆ THÔNG TIN VÀ LIÊN HỆ KHÁCH HÀNG",
      "paragraphs": [
        "Hai bên chỉ xử lý dữ liệu định danh, liên lạc, phương tiện, chuyến đi và thuế trong phạm vi cần thiết để thực hiện hợp đồng, bảo đảm an toàn, giải quyết tranh chấp và thực hiện nghĩa vụ pháp luật. Bên A có thể cung cấp dữ liệu cần thiết cho cơ quan có thẩm quyền hoặc đơn vị xử lý dữ liệu, dịch vụ thuế hợp pháp trong phạm vi công việc và phải có biện pháp bảo mật phù hợp.",
        "Để phục vụ chuyến đi, tài xế và khách có thể liên hệ qua ứng dụng GoViet247 hoặc gọi trực tiếp bằng số điện thoại hiển thị trên chuyến. Với chuyến đối tác, tài xế liên hệ điều phối viên phụ trách. Chỉ sử dụng thông tin liên hệ cho chuyến đã nhận và không dùng để mời chào hoặc nhận chuyến ngoài hệ thống.",
        "Số liên hệ được hiển thị cho người tham gia có quyền xem khi chuyến đang thực hiện. Tài xế có thể sao chép số trong mục Đơn của tôi. Với chuyến đối tác, đầu mối hiển thị cho tài xế là điều phối viên được phân công. Các bên chỉ gọi hoặc thao tác trên điện thoại khi bảo đảm an toàn.",
